INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Anycast nur für DNS-Server relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch für CDNs und andere Dienste nutzbar"}, {"text": "Ja", "correct": false, "because": "Vielseitig einsetzbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Protokoll nutzt Anycast typischerweise?', 3, '[{"text": "BGP", "correct": true, "because": "Border Gateway Protocol für Routing"}, {"text": "OSPF", "correct": false, "because": "Interne Netzwerke"}, {"text": "TCP", "correct": false, "because": "Transportprotokoll"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet Anycast?', 5, '[{"text": "Geringere Latenz", "correct": true, "because": "Nächstgelegener Server"}, {"text": "Lastverteilung", "correct": true, "because": "Traffic verteilt"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anycast nutzt eine einzige IP-Adresse. b) Es erfordert identische Server.', 3, '[{"text": "Beides stimmt", "correct": true, "because": "Einheitliche IP und Serverkonfiguration"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) auch korrekt"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) auch korrekt"}, {"text": "Beides falsch", "correct": false, "because": "Beide richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei Anycast-Routing?', 4, '[{"text": "Serverstandort", "correct": false, "because": "Entscheidend für Nähe"}, {"text": "Routing-Protokoll", "correct": false, "because": "Kern der Methode"}, {"text": "Serverfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anycast Redundanz bietet?', 2, '[{"text": "Ja", "correct": true, "because": "Automatische Umleitung"}, {"text": "Nein", "correct": false, "because": "Hohe Verfügbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technologie nutzt Anycast für die Weiterleitung?', 3, '[{"text": "BGP", "correct": true, "because": "Wählt kürzeste Route"}, {"text": "DHCP", "correct": false, "because": "Adresszuweisung"}, {"text": "FTP", "correct": false, "because": "Dateitransfer"}]'),
('00000000-0000-0000-0000-000000000000', 'Was gehört zur Anycast-Konfiguration?', 5, '[{"text": "Gleiche IP-Adresse", "correct": true, "because": "Einheitliche Adressierung"}, {"text": "Routing-Ankündigung", "correct": true, "because": "BGP-Ankündigungen"}, {"text": "Unterschiedliche IPs", "correct": false, "because": "Gegen Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Anycast verbessert die Latenz. b) Es ist nur für große Netzwerke. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch kleine Netzwerke nutzbar"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Anycast unwichtig?', 4, '[{"text": "Serverproximität", "correct": false, "because": "Entscheidend für Latenz"}, {"text": "Routing-Konfiguration", "correct": false, "because": "Grundlage"}, {"text": "Servermarke", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Nutzt Anycast Unicast-Adressen?', 2, '[{"text": "Nein", "correct": true, "because": "Gemeinsame IP"}, {"text": "Ja", "correct": false, "because": "Anycast-Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Nachteile hat Anycast?', 4, '[{"text": "Komplexe Synchronisation", "correct": true, "because": "Datenkonsistenz"}, {"text": "Begrenzte Kontrolle", "correct": true, "because": "Routing-abhängig"}, {"text": "Hohe Latenz", "correct": false, "because": "Reduziert Latenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Anycast nur für UDP geeignet ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Auch TCP möglich"}, {"text": "Ja", "correct": false, "because": "Vielseitig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei Anycast?', 3, '[{"text": "Nähe zum Nutzer", "correct": true, "because": "Reduziert Latenz"}, {"text": "Serveranzahl", "correct": false, "because": "Sekundär"}, {"text": "Kosten", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Anycast verteilt Lasten. b) Es erfordert keine Synchronisation.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Synchronisation nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anwendung nutzt Anycast häufig?', 5, '[{"text": "DNS", "correct": true, "because": "Schnelle Auflösung"}, {"text": "CDN", "correct": true, "because": "Inhalte näher"}, {"text": "E-Mail", "correct": false, "because": "Weniger üblich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei Anycast-Routing unwichtig?', 3, '[{"text": "BGP-Konfiguration", "correct": false, "because": "Kern der Methode"}, {"text": "Serverstandorte", "correct": false, "because": "Entscheidend"}, {"text": "Servergewicht", "correct": true, "because": "Kein Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Anycast DDoS-Schutz bieten?', 3, '[{"text": "Ja", "correct": true, "because": "Traffic verteilt"}, {"text": "Nein", "correct": false, "because": "Schutzfähig"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Anycast Skalierbarkeit fördert?', 2, '[{"text": "Ja", "correct": true, "because": "Server leicht hinzufügbar"}, {"text": "Nein", "correct": false, "because": "Skalierbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode wähle ich für Anycast?', 4, '[{"text": "BGP-Ankündigungen", "correct": true, "because": "Effektives Routing"}, {"text": "Statische Routen", "correct": false, "because": "Weniger dynamisch"}, {"text": "DNS-Failover", "correct": false, "because": "Andere Technik"}]');
